    (1, 'uz', $q$Qaysi davlatni tanlash kerak?$q$, $a$Epic Games akkauntingiz roʻyxatdan oʻtgan davlatni, PlayStation da oʻynasangiz — PlayStation Network akkauntingiz davlatini. Boshqa davlat kartasi faollashmaydi.$a$),
    (2, 'ru', $q$Как оплатить?$q$, $a$Оплата в сумах через Click, Payme или Uzum. Итог в сумах виден до оплаты, и списывается ровно он.$a$),
    (2, 'en', $q$How do I pay?$q$, $a$Pay in soʻm with Click, Payme or Uzum. You see the total in soʻm before paying, and exactly that amount is charged.$a$),
    (2, 'uz', $q$Qanday toʻlash mumkin?$q$, $a$Click, Payme yoki Uzum orqali soʻmda toʻlov. Soʻmdagi yakuniy summa toʻlovdan oldin koʻrinadi va aynan shu summa yechiladi.$a$),
    (3, 'ru', $q$На какой платформе будут V-Bucks?$q$, $a$V-Bucks, погашенные на PlayStation, Xbox, ПК или мобильных устройствах, общие для этих платформ. Погашенные на Nintendo тратятся только на Nintendo.$a$),
    (3, 'en', $q$Which platform will the V-Bucks be on?$q$, $a$V-Bucks redeemed on PlayStation, Xbox, PC or mobile are shared across those platforms. V-Bucks redeemed on Nintendo can only be spent on Nintendo.$a$),
    (3, 'uz', $q$V-Bucks qaysi platformada boʻladi?$q$, $a$PlayStation, Xbox, PK yoki mobil qurilmalarda faollashtirilgan V-Bucks shu platformalar uchun umumiy. Nintendo da faollashtirilganlari faqat Nintendo da sarflanadi.$a$),
    (4, 'ru', $q$Где мой код?$q$, $a$На странице заказа и в письме на почту, указанную при заказе. Если письма нет — проверьте «Спам» и «Промоакции».$a$),
    (4, 'en', $q$Where is my code?$q$, $a$On the order page and in an email to the address on the order. If the email is not there, check Spam and Promotions.$a$),
    (4, 'uz', $q$Kodim qayerda?$q$, $a$Buyurtma sahifasida va buyurtmada koʻrsatilgan pochtaga kelgan xatda. Xat boʻlmasa — «Spam» va «Promotions» papkalarini tekshiring.$a$)
) AS t(so, locale, question, answer) ON t.so = nf.sort_order;

-- call-of-duty-mobile
UPDATE brand_translations SET
    seo_title = $c$Call of Duty: Mobile CP — пополнить по UID в Узбекистане за сумы$c$,
    seo_description = $c$Пополнение CP в Call of Duty: Mobile по UID игрока, без пароля. Версия Activision: Казахстан, США, Канада, Индия, Саудовская Аравия. Оплата в сумах через Click, Payme или Uzum.$c$,
    short_description = $c$CP для Call of Duty: Mobile по UID игрока. Пароль не нужен, оплата в сумах.$c$,
    description = $c$CP (COD Points) — валюта Call of Duty: Mobile. На неё покупают боевой пропуск, оружие и персонажей.

Пополнение идёт по UID игрока. Код вводить не нужно, пароль не нужен. Подходит для версии игры от Activision.

Выберите регион и сумму, укажите UID и оплатите. CP придут на аккаунт после оплаты.$c$,
    instructions = $c$Как пополнить:

1. В игре на главном экране нажмите на свой никнейм в левом верхнем углу и откройте вторую вкладку — профиль.
2. Скопируйте UID — длинное число (около 20 цифр) под никнеймом.
3. Выберите регион и сумму CP выше и вставьте UID.
4. Оплатите заказ и перезайдите в игру.

CP зачисляются на аккаунт по ID игрока после оплаты. Пароль не нужен.$c$,
    highlights = $c$["Оплата в сумах", "По ID игрока", "Без пароля", "Регион на выбор"]$c$::json
WHERE brand_id = (SELECT id FROM brands WHERE slug = 'call-of-duty-mobile') AND locale = 'ru';
UPDATE brand_translations SET
    seo_title = $c$Call of Duty: Mobile CP — top up by UID in Uzbekistan for soʻm$c$,
    seo_description = $c$Call of Duty: Mobile CP top-up by Player UID, no password. Activision version: Kazakhstan, US, Canada, India, Saudi Arabia. Pay in soʻm with Click, Payme or Uzum.$c$,
    short_description = $c$CP for Call of Duty: Mobile by Player UID. No password, pay in soʻm.$c$,
    description = $c$CP (COD Points) is the currency of Call of Duty: Mobile. It buys the battle pass, weapons and characters.

The top-up goes by Player UID. No code to enter, no password. It is for the Activision version of the game.

Pick a region and amount, enter your UID and pay. The CP arrives on the account after payment.$c$,
    instructions = $c$How to top up:

1. In the game, on the home screen, tap your nickname at the top left and open the second tab — your profile.
2. Copy your UID — the long number (about 20 digits) under your nickname.
3. Pick a region and CP amount above and paste the UID.
4. Pay for the order and restart the game.

CP is credited to the account by Player ID after payment. No password needed.$c$,
    highlights = $c$["Pay in UZS", "By Player ID", "No password", "Pick your region"]$c$::json
WHERE brand_id = (SELECT id FROM brands WHERE slug = 'call-of-duty-mobile') AND locale = 'en';
UPDATE brand_translations SET
    seo_title = $c$Call of Duty: Mobile CP — Oʻzbekistonda UID orqali soʻmga toʻldirish$c$,
    seo_description = $c$Call of Duty: Mobile da CP ni oʻyinchi UID si orqali toʻldirish, parolsiz. Activision versiyasi: Qozogʻiston, AQSH, Kanada, Hindiston, Saudiya Arabistoni. Click, Payme yoki Uzum orqali soʻmda toʻlov.$c$,
    short_description = $c$Call of Duty: Mobile uchun oʻyinchi UID si orqali CP. Parol kerak emas, soʻmda toʻlov.$c$,
    description = $c$CP (COD Points) — Call of Duty: Mobile valyutasi. Unga jangovar propusk, qurollar va personajlar olinadi.

Toʻldirish oʻyinchi UID si orqali. Kod kiritish shart emas, parol kerak emas. Oʻyinning Activision versiyasi uchun.

Mintaqa va summani tanlang, UID ni kiriting va toʻlang. CP toʻlovdan soʻng akkauntga tushadi.$c$,
    instructions = $c$Qanday toʻldirish:

1. Oʻyinda bosh ekranda yuqori chap burchakdagi nikneymingizni bosing va ikkinchi tabni — profilni oching.
2. UID ni nusxalang — nikneym ostidagi uzun raqam (taxminan 20 ta raqam).
3. Yuqorida mintaqa va CP summasini tanlang, UID ni kiriting.
4. Buyurtmani toʻlang va oʻyinga qayta kiring.

CP toʻlovdan soʻng oʻyinchi ID si orqali akkauntga tushadi. Parol kerak emas.$c$,
    highlights = $c$["Soʻmda toʻlov", "Oʻyinchi ID orqali", "Parolsiz", "Hududni tanlang"]$c$::json
WHERE brand_id = (SELECT id FROM brands WHERE slug = 'call-of-duty-mobile') AND locale = 'uz';
DELETE FROM brand_faqs WHERE brand_id = (SELECT id FROM brands WHERE slug = 'call-of-duty-mobile');
WITH nf AS (
    INSERT INTO brand_faqs (id, brand_id, sort_order, active)
    SELECT gen_random_uuid(), b.id, v.so, true
      FROM brands b, (VALUES (1), (2), (3), (4)) AS v(so)
     WHERE b.slug = 'call-of-duty-mobile'
    RETURNING id, sort_order
)
INSERT INTO brand_faq_translations (brand_faq_id, locale, question, answer)
SELECT nf.id, t.locale, t.question, t.answer
  FROM nf JOIN (VALUES
    (1, 'ru', $q$Где найти UID?$q$, $a$В игре нажмите на свой никнейм в левом верхнем углу главного экрана и откройте вторую вкладку. UID — длинное число под никнеймом. Проверьте его перед оплатой: CP придут на тот аккаунт, чей UID указан.$a$),
    (1, 'en', $q$Where do I find my UID?$q$, $a$In the game, tap your nickname at the top left of the home screen and open the second tab. The UID is the long number under your nickname. Check it before paying: the CP goes to the account whose UID you entered.$a$),
    (1, 'uz', $q$UID ni qayerdan topaman?$q$, $a$Oʻyinda bosh ekranning yuqori chap burchagidagi nikneymingizni bosing va ikkinchi tabni oching. UID — nikneym ostidagi uzun raqam. Toʻlashdan oldin tekshiring: CP UID si kiritilgan akkauntga tushadi.$a$),
    (2, 'ru', $q$Какая версия игры подходит?$q$, $a$Версия от Activision. Версии Garena для Юго-Восточной Азии здесь не пополняются.$a$),
    (2, 'en', $q$Which version of the game does this fit?$q$, $a$The Activision version. Garena versions for Southeast Asia cannot be topped up here.$a$),
    (2, 'uz', $q$Oʻyinning qaysi versiyasiga mos?$q$, $a$Activision versiyasi. Janubi-Sharqiy Osiyo uchun Garena versiyalari bu yerda toʻldirilmaydi.$a$),
    (3, 'ru', $q$Нужен ли пароль от аккаунта?$q$, $a$Нет. Нужен только UID. Никому не сообщайте пароль.$a$),
    (3, 'en', $q$Do you need my account password?$q$, $a$No. Only the UID. Never share your password with anyone.$a$),
    (3, 'uz', $q$Akkaunt paroli kerakmi?$q$, $a$Yoʻq. Faqat UID kerak. Parolingizni hech kimga bermang.$a$),
    (4, 'ru', $q$Как оплатить?$q$, $a$Оплата в сумах через Click, Payme или Uzum. Итог в сумах виден до оплаты, и списывается ровно он.$a$),
    (4, 'en', $q$How do I pay?$q$, $a$Pay in soʻm with Click, Payme or Uzum. You see the total in soʻm before paying, and exactly that amount is charged.$a$),
    (4, 'uz', $q$Qanday toʻlash mumkin?$q$, $a$Click, Payme yoki Uzum orqali soʻmda toʻlov. Soʻmdagi yakuniy summa toʻlovdan oldin koʻrinadi va aynan shu summa yechiladi.$a$)
) AS t(so, locale, question, answer) ON t.so = nf.sort_order;

-- ea-sports-fc-26-ea-points
UPDATE brand_translations SET
    seo_title = $c$EA SPORTS FC 26 Points — купить в Узбекистане за сумы$c$,
    seo_description = $c$Коды FC Points для EA SPORTS FC 26 на ПК: 1050, 2800, 5900, 12000 и 18500 очков. Код на почту после оплаты. Оплата в сумах через Click, Payme или Uzum.$c$,
    short_description = $c$Коды FC Points для EA SPORTS FC 26 на ПК. Код на почту, оплата в сумах.$c$,
    description = $c$FC Points — валюта EA SPORTS FC 26. На неё покупают наборы в Ultimate Team.

Код для ПК-версии. Он погашается на аккаунте EA, с которого вы играете. Очки остаются на своей платформе: на PlayStation или Xbox их не перенести.

Код виден на странице заказа и приходит на почту после оплаты.$c$,
    instructions = $c$Как активировать код:

1. Запустите EA app и войдите в аккаунт EA, с которого играете в FC 26.
2. Откройте «Моя библиотека» (My Library) и выберите «Активировать код» (Redeem Code).
3. Введите код из письма и подтвердите.
4. Или откройте ea.com/redeem, нажмите Redeem для ПК-кодов и введите код.
5. Запустите FC 26 и войдите в Ultimate Team — очки будут на балансе.

Код появится на странице заказа и придёт на почту после оплаты.$c$,
    highlights = $c$["Оплата в сумах", "Код на почту", "Без пароля"]$c$::json
WHERE brand_id = (SELECT id FROM brands WHERE slug = 'ea-sports-fc-26-ea-points') AND locale = 'ru';
UPDATE brand_translations SET
    seo_title = $c$EA SPORTS FC 26 Points — buy in Uzbekistan for soʻm$c$,
    seo_description = $c$FC Points codes for EA SPORTS FC 26 on PC: 1050, 2800, 5900, 12000 and 18500 points. Code by email after payment. Pay in soʻm with Click, Payme or Uzum.$c$,
    short_description = $c$FC Points codes for EA SPORTS FC 26 on PC. Code by email, pay in soʻm.$c$,
    description = $c$FC Points are the currency of EA SPORTS FC 26. They buy packs in Ultimate Team.

The code is for the PC version. Redeem it on the EA account you play on. Points stay on their platform: they cannot be moved to PlayStation or Xbox.

The code shows on the order page and arrives by email after payment.$c$,
    instructions = $c$How to redeem the code:

1. Launch the EA app and sign in to the EA account you play FC 26 on.
2. Open My Library and choose Redeem Code.
3. Enter the code from the email and confirm.
4. Or open ea.com/redeem, click Redeem for PC codes and enter the code.
5. Launch FC 26 and enter Ultimate Team — the points are on your balance.

The code appears on the order page and is emailed to you after payment.$c$,
    highlights = $c$["Pay in UZS", "Code by email", "No password"]$c$::json
WHERE brand_id = (SELECT id FROM brands WHERE slug = 'ea-sports-fc-26-ea-points') AND locale = 'en';
UPDATE brand_translations SET
    seo_title = $c$EA SPORTS FC 26 Points — Oʻzbekistonda soʻmga sotib olish$c$,
    seo_description = $c$PK dagi EA SPORTS FC 26 uchun FC Points kodlari: 1050, 2800, 5900, 12000 va 18500 ochko. Kod toʻlovdan soʻng pochtaga. Click, Payme yoki Uzum orqali soʻmda toʻlov.$c$,
    short_description = $c$PK dagi EA SPORTS FC 26 uchun FC Points kodlari. Kod pochtaga, soʻmda toʻlov.$c$,
    description = $c$FC Points — EA SPORTS FC 26 valyutasi. Unga Ultimate Team da toʻplamlar olinadi.

Kod PK versiyasi uchun. U siz oʻynaydigan EA akkauntida faollashtiriladi. Ochkolar oʻz platformasida qoladi: PlayStation yoki Xbox ga oʻtkazib boʻlmaydi.

Kod toʻlovdan soʻng buyurtma sahifasida koʻrinadi va pochtaga keladi.$c$,
    instructions = $c$Kodni qanday faollashtirish:

1. EA app ni ishga tushiring va FC 26 oʻynaydigan EA akkauntingizga kiring.
2. «My Library» ni oching va «Redeem Code» ni tanlang.
3. Xatdagi kodni kiriting va tasdiqlang.
4. Yoki ea.com/redeem ni oching, PK kodlari uchun Redeem ni bosing va kodni kiriting.
5. FC 26 ni ishga tushiring va Ultimate Team ga kiring — ochkolar balansda boʻladi.

Kod toʻlovdan soʻng buyurtma sahifasida chiqadi va pochtaga keladi.$c$,
    highlights = $c$["Soʻmda toʻlov", "Kod pochtaga", "Parolsiz"]$c$::json
WHERE brand_id = (SELECT id FROM brands WHERE slug = 'ea-sports-fc-26-ea-points') AND locale = 'uz';
DELETE FROM brand_faqs WHERE brand_id = (SELECT id FROM brands WHERE slug = 'ea-sports-fc-26-ea-points');
WITH nf AS (
    INSERT INTO brand_faqs (id, brand_id, sort_order, active)
    SELECT gen_random_uuid(), b.id, v.so, true
      FROM brands b, (VALUES (1), (2), (3), (4)) AS v(so)
     WHERE b.slug = 'ea-sports-fc-26-ea-points'
    RETURNING id, sort_order
)
INSERT INTO brand_faq_translations (brand_faq_id, locale, question, answer)
SELECT nf.id, t.locale, t.question, t.answer
  FROM nf JOIN (VALUES
    (1, 'ru', $q$Код подойдёт для PlayStation или Xbox?$q$, $a$Нет. Код для ПК-версии FC 26. Очки, погашенные на ПК, на консоли не переносятся.$a$),
    (1, 'en', $q$Will the code work on PlayStation or Xbox?$q$, $a$No. The code is for the PC version of FC 26. Points redeemed on PC cannot be moved to a console.$a$),
    (1, 'uz', $q$Kod PlayStation yoki Xbox uchun mos keladimi?$q$, $a$Yoʻq. Kod FC 26 ning PK versiyasi uchun. PK da faollashtirilgan ochkolar konsolga oʻtkazilmaydi.$a$),
    (2, 'ru', $q$Как оплатить?$q$, $a$Оплата в сумах через Click, Payme или Uzum. Итог в сумах виден до оплаты, и списывается ровно он.$a$),
    (2, 'en', $q$How do I pay?$q$, $a$Pay in soʻm with Click, Payme or Uzum. You see the total in soʻm before paying, and exactly that amount is charged.$a$),
    (2, 'uz', $q$Qanday toʻlash mumkin?$q$, $a$Click, Payme yoki Uzum orqali soʻmda toʻlov. Soʻmdagi yakuniy summa toʻlovdan oldin koʻrinadi va aynan shu summa yechiladi.$a$),
    (3, 'ru', $q$Где мой код?$q$, $a$На странице заказа и в письме на почту, указанную при заказе. Если письма нет — проверьте «Спам» и «Промоакции».$a$),
    (3, 'en', $q$Where is my code?$q$, $a$On the order page and in an email to the address on the order. If the email is not there, check Spam and Promotions.$a$),
    (3, 'uz', $q$Kodim qayerda?$q$, $a$Buyurtma sahifasida va buyurtmada koʻrsatilgan pochtaga kelgan xatda. Xat boʻlmasa — «Spam» va «Promotions» papkalarini tekshiring.$a$),
    (4, 'ru', $q$Я погасил код, а очков в игре нет. Что делать?$q$, $a$Проверьте, что код погашен на том аккаунте EA, с которого вы играете. Затем перезапустите игру и снова войдите в Ultimate Team.$a$),
    (4, 'en', $q$I redeemed the code but see no points in the game. What now?$q$, $a$Check that you redeemed the code on the EA account you play on. Then restart the game and enter Ultimate Team again.$a$),
    (4, 'uz', $q$Kodni faollashtirdim, lekin oʻyinda ochko yoʻq. Nima qilish kerak?$q$, $a$Kod siz oʻynaydigan EA akkauntida faollashtirilganini tekshiring. Soʻng oʻyinni qayta ishga tushiring va Ultimate Team ga qayta kiring.$a$)
) AS t(so, locale, question, answer) ON t.so = nf.sort_order;

-- pubg-battlegrounds
UPDATE brand_translations SET
    seo_title = $c$PUBG: BATTLEGROUNDS G-Coin — купить в Узбекистане за сумы$c$,
    seo_description = $c$Коды G-Coin для PUBG: BATTLEGROUNDS на ПК: от 100 до 11200 G-Coin. Код на почту после оплаты. Оплата в сумах через Click, Payme или Uzum.$c$,
    short_description = $c$Коды G-Coin для PUBG: BATTLEGROUNDS на ПК. Код на почту, оплата в сумах.$c$,
    description = $c$G-Coin — валюта PUBG: BATTLEGROUNDS. На неё покупают предметы в игровом магазине: скины, наборы, Survivor Pass.

Код для ПК-версии игры. Для консолей и PUBG Mobile он не подходит.

Код виден на странице заказа и приходит на почту после оплаты.$c$,
    instructions = $c$Как активировать код:

1. Запустите PUBG: BATTLEGROUNDS на ПК и войдите в свой аккаунт.
2. В лобби откройте магазин (Store) и найдите пункт ввода кода.
3. Введите код из письма и подтвердите.
4. G-Coin зачислятся на баланс — его видно в магазине.

Код появится на странице заказа и придёт на почту после оплаты.$c$,
    highlights = $c$["Оплата в сумах", "Код на почту", "Без пароля"]$c$::json
WHERE brand_id = (SELECT id FROM brands WHERE slug = 'pubg-battlegrounds') AND locale = 'ru';
UPDATE brand_translations SET
    seo_title = $c$PUBG: BATTLEGROUNDS G-Coin — buy in Uzbekistan for soʻm$c$,
    seo_description = $c$G-Coin codes for PUBG: BATTLEGROUNDS on PC: 100 to 11200 G-Coin. Code by email after payment. Pay in soʻm with Click, Payme or Uzum.$c$,
    short_description = $c$G-Coin codes for PUBG: BATTLEGROUNDS on PC. Code by email, pay in soʻm.$c$,
    description = $c$G-Coin is the currency of PUBG: BATTLEGROUNDS. It buys items in the in-game Store: skins, bundles, the Survivor Pass.

The code is for the PC version of the game. It does not fit consoles or PUBG Mobile.

The code shows on the order page and arrives by email after payment.$c$,
    instructions = $c$How to redeem the code:

1. Launch PUBG: BATTLEGROUNDS on PC and sign in to your account.
2. In the lobby, open the Store and find the option to enter a code.
3. Enter the code from the email and confirm.
4. The G-Coin lands on your balance — you can see it in the Store.

The code appears on the order page and is emailed to you after payment.$c$,
    highlights = $c$["Pay in UZS", "Code by email", "No password"]$c$::json
WHERE brand_id = (SELECT id FROM brands WHERE slug = 'pubg-battlegrounds') AND locale = 'en';
UPDATE brand_translations SET
    seo_title = $c$PUBG: BATTLEGROUNDS G-Coin — Oʻzbekistonda soʻmga sotib olish$c$,
    seo_description = $c$PK dagi PUBG: BATTLEGROUNDS uchun G-Coin kodlari: 100 dan 11200 G-Coin gacha. Kod toʻlovdan soʻng pochtaga. Click, Payme yoki Uzum orqali soʻmda toʻlov.$c$,
    short_description = $c$PK dagi PUBG: BATTLEGROUNDS uchun G-Coin kodlari. Kod pochtaga, soʻmda toʻlov.$c$,
    description = $c$G-Coin — PUBG: BATTLEGROUNDS valyutasi. Unga oʻyin doʻkonidagi buyumlar olinadi: skinlar, toʻplamlar, Survivor Pass.

Kod oʻyinning PK versiyasi uchun. Konsollar va PUBG Mobile uchun mos emas.

Kod toʻlovdan soʻng buyurtma sahifasida koʻrinadi va pochtaga keladi.$c$,
    instructions = $c$Kodni qanday faollashtirish:

1. PK da PUBG: BATTLEGROUNDS ni ishga tushiring va akkauntingizga kiring.
2. Lobbida doʻkonni (Store) oching va kod kiritish boʻlimini toping.
3. Xatdagi kodni kiriting va tasdiqlang.
4. G-Coin balansga tushadi — uni doʻkonda koʻrasiz.

Kod toʻlovdan soʻng buyurtma sahifasida chiqadi va pochtaga keladi.$c$,
    highlights = $c$["Soʻmda toʻlov", "Kod pochtaga", "Parolsiz"]$c$::json
WHERE brand_id = (SELECT id FROM brands WHERE slug = 'pubg-battlegrounds') AND locale = 'uz';
DELETE FROM brand_faqs WHERE brand_id = (SELECT id FROM brands WHERE slug = 'pubg-battlegrounds');
WITH nf AS (
    INSERT INTO brand_faqs (id, brand_id, sort_order, active)
    SELECT gen_random_uuid(), b.id, v.so, true
      FROM brands b, (VALUES (1), (2), (3), (4)) AS v(so)
     WHERE b.slug = 'pubg-battlegrounds'
    RETURNING id, sort_order
)
INSERT INTO brand_faq_translations (brand_faq_id, locale, question, answer)
SELECT nf.id, t.locale, t.question, t.answer
  FROM nf JOIN (VALUES
    (1, 'ru', $q$Подойдёт ли код для PUBG Mobile или консоли?$q$, $a$Нет. Код только для PUBG: BATTLEGROUNDS на ПК. PUBG Mobile — другая игра со своей валютой (UC).$a$),
    (1, 'en', $q$Will the code work for PUBG Mobile or a console?$q$, $a$No. The code is only for PUBG: BATTLEGROUNDS on PC. PUBG Mobile is a different game with its own currency (UC).$a$),
    (1, 'uz', $q$Kod PUBG Mobile yoki konsol uchun mos keladimi?$q$, $a$Yoʻq. Kod faqat PK dagi PUBG: BATTLEGROUNDS uchun. PUBG Mobile — oʻz valyutasi (UC) bor boshqa oʻyin.$a$),
    (2, 'ru', $q$Как оплатить?$q$, $a$Оплата в сумах через Click, Payme или Uzum. Итог в сумах виден до оплаты, и списывается ровно он.$a$),
    (2, 'en', $q$How do I pay?$q$, $a$Pay in soʻm with Click, Payme or Uzum. You see the total in soʻm before paying, and exactly that amount is charged.$a$),
    (2, 'uz', $q$Qanday toʻlash mumkin?$q$, $a$Click, Payme yoki Uzum orqali soʻmda toʻlov. Soʻmdagi yakuniy summa toʻlovdan oldin koʻrinadi va aynan shu summa yechiladi.$a$),
    (3, 'ru', $q$Где мой код?$q$, $a$На странице заказа и в письме на почту, указанную при заказе. Если письма нет — проверьте «Спам» и «Промоакции».$a$),
    (3, 'en', $q$Where is my code?$q$, $a$On the order page and in an email to the address on the order. If the email is not there, check Spam and Promotions.$a$),
    (3, 'uz', $q$Kodim qayerda?$q$, $a$Buyurtma sahifasida va buyurtmada koʻrsatilgan pochtaga kelgan xatda. Xat boʻlmasa — «Spam» va «Promotions» papkalarini tekshiring.$a$),
    (4, 'ru', $q$Что купить на G-Coin?$q$, $a$Предметы в игровом магазине PUBG: BATTLEGROUNDS — скины, наборы и Survivor Pass.$a$),
    (4, 'en', $q$What can I buy with G-Coin?$q$, $a$Items in the PUBG: BATTLEGROUNDS in-game Store — skins, bundles and the Survivor Pass.$a$),
    (4, 'uz', $q$G-Coin ga nima olish mumkin?$q$, $a$PUBG: BATTLEGROUNDS oʻyin doʻkonidagi buyumlar — skinlar, toʻplamlar va Survivor Pass.$a$)
) AS t(so, locale, question, answer) ON t.so = nf.sort_order;

-- The owner's payment wording, everywhere an earlier seed said «no fee».
UPDATE brand_faq_translations SET answer = replace(answer, $c$ Итог в сумах виден до подтверждения, комиссии сверху нет.$c$, $c$ Итог в сумах виден до оплаты, и списывается ровно он.$c$)
 WHERE locale = 'ru' AND position($c$ Итог в сумах виден до подтверждения, комиссии сверху нет.$c$ in answer) > 0;
UPDATE brand_faq_translations SET answer = replace(answer, $c$ The total in soʻm is shown before you confirm, with no extra fee.$c$, $c$ The total in soʻm is shown before you pay, and exactly that is charged.$c$)
 WHERE locale = 'en' AND position($c$ The total in soʻm is shown before you confirm, with no extra fee.$c$ in answer) > 0;
UPDATE brand_faq_translations SET answer = replace(answer, $c$ Yakuniy summa soʻmda tasdiqlashdan oldin koʻrinadi, ustiga komissiya yoʻq.$c$, $c$ Yakuniy summa soʻmda toʻlovdan oldin koʻrinadi va aynan u yechiladi.$c$)
 WHERE locale = 'uz' AND position($c$ Yakuniy summa soʻmda tasdiqlashdan oldin koʻrinadi, ustiga komissiya yoʻq.$c$ in answer) > 0;

SELECT b.slug, t.locale, t.seo_title,
       (SELECT count(*) FROM brand_faqs f WHERE f.brand_id = b.id) AS faqs
  FROM brands b JOIN brand_translations t ON t.brand_id = b.id
 WHERE b.slug IN ('valorant', 'league-of-legends', 'fortnite', 'call-of-duty-mobile', 'ea-sports-fc-26-ea-points', 'pubg-battlegrounds')
 ORDER BY 1, 2;
SELECT count(*) AS no_fee_left FROM brand_faq_translations
 WHERE answer ILIKE '%комиссии сверху нет%' OR answer ILIKE '%no extra fee%'
    OR answer ILIKE '%ustiga komissiya yoʻq%';

COMMIT;
